    if (v === 'zh' || v.startsWith('zh-cn') || v.startsWith('zh-hans')) return 'zh-cn';
    if (v.startsWith('zh-tw') || v.startsWith('zh-hk') || v.startsWith('zh-hant')) return 'zh-tw';
